import { z } from 'zod';
import { uuid } from './common';

/**
 * Loose ceiling so an oversized payload is rejected before the database call. The real limit
 * (and the per-minute rate) lives in `messaging_config` and is enforced by `send_job_message`.
 */
const MESSAGE_PAYLOAD_CEILING = 10_000;

export const sendMessageSchema = z.object({
  jobId: uuid,
  body: z.string().trim().min(1, 'Write a message first').max(MESSAGE_PAYLOAD_CEILING, 'That message is too long'),
  /** Generated by the browser per message; a retry with the same key is stored once. */
  clientKey: uuid,
});
export type SendMessageInput = z.infer<typeof sendMessageSchema>;

export const markThreadReadSchema = z.object({ jobId: uuid });
export type MarkThreadReadInput = z.infer<typeof markThreadReadSchema>;

export const markNotificationReadSchema = z.object({ notificationId: uuid });
export type MarkNotificationReadInput = z.infer<typeof markNotificationReadSchema>;
